def search_pubmed_advanced(term=None, title=None, author=None, journal=None, start_date=None, end_date=None, num_results=10, **_extra):
    import json, os, datetime, time, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0306000" if __import__("os").path.isdir("./environment_mix/0306000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    def _parse_date(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "TYPE_ERROR"
        ss = s.strip()
        if ss == "":
            return "MALFORMED"
        # Accept YYYY, YYYY-MM, YYYY-MM-DD as "well-formed". Compare by earliest possible date.
        try:
            if re.fullmatch(r"\d{4}", ss):
                return datetime.date(int(ss), 1, 1)
            if re.fullmatch(r"\d{4}-\d{2}", ss):
                y, m = ss.split("-")
                return datetime.date(int(y), int(m), 1)
            if re.fullmatch(r"\d{4}-\d{2}-\d{2}", ss):
                y, m, d = ss.split("-")
                return datetime.date(int(y), int(m), int(d))
        except Exception:
            return "MALFORMED"
        return "MALFORMED"

    def _parse_iso_dt(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1]
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{os.getpid()}_{random.randint(1000,9999)}"

    def _select_active_client():
        clients = _load("api_clients.json")
        if not isinstance(clients, list):
            clients = []
        # Choose any active client that has sane limits; this tool has no explicit credential parameter.
        for c in clients:
            if not isinstance(c, dict):
                continue
            if c.get("status") != "active":
                continue
            rpm = c.get("requests_per_minute_limit")
            daily = c.get("daily_request_limit")
            if isinstance(rpm, int) and 1 <= rpm <= 6000 and isinstance(daily, int) and 1 <= daily <= 1000000:
                return c
        return None

    def _check_limits(api_client):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        api_client_id = api_client.get("id")
        rpm_limit = api_client.get("requests_per_minute_limit")
        daily_limit = api_client.get("daily_request_limit")
        win_start = now_dt - datetime.timedelta(seconds=60)
        day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
        c60 = 0
        cday = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_client_id") != api_client_id:
                continue
            dt = _parse_iso_dt(r.get("created_at"))
            if dt is None:
                continue
            if dt >= win_start:
                c60 += 1
            if dt >= day_start:
                cday += 1
        if isinstance(rpm_limit, int) and c60 >= rpm_limit:
            return _err("RATE_LIMIT", "Requests per minute limit exceeded.", limit=rpm_limit, window_seconds=60)
        if isinstance(daily_limit, int) and cday >= daily_limit:
            return _err("QUOTA_EXCEEDED", "Daily request limit exceeded.", limit=daily_limit, window="day")
        return None

    def _log(api_client_id, status_str, error_code=None):
        latency_ms = int((time.time() - _t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_id("rlog"),
            "api_client_id": api_client_id,
            "tool_name": "search_pubmed_advanced",
            "status": status_str,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now_iso
        })
        _save("request_logs.json", logs)

    # ---- Validate inputs (relaxed per audit: do NOT reject all-null advanced search) ----
    for nm, v in [("term", term), ("title", title), ("author", author), ("journal", journal), ("start_date", start_date), ("end_date", end_date)]:
        if v is not None and not isinstance(v, str):
            # log with any available client context later; for now return after selecting client & logging
            pass

    if num_results is None:
        num_results = 10
    if not isinstance(num_results, int):
        client = _select_active_client()
        if client:
            _log(client.get("id"), "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "num_results must be an integer.")
    if num_results < 1 or num_results > 500:
        client = _select_active_client()
        if client:
            _log(client.get("id"), "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "num_results must be between 1 and 500.", min=1, max=500)

    # Validate string types
    for nm, v in [("term", term), ("title", title), ("author", author), ("journal", journal), ("start_date", start_date), ("end_date", end_date)]:
        if v is not None and not isinstance(v, str):
            client = _select_active_client()
            if client:
                _log(client.get("id"), "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"{nm} must be a string or null.")

    sd = _parse_date(start_date) if start_date is not None else None
    ed = _parse_date(end_date) if end_date is not None else None
    if sd in ("TYPE_ERROR", "MALFORMED"):
        client = _select_active_client()
        if client:
            _log(client.get("id"), "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_date is malformed. Use YYYY, YYYY-MM, or YYYY-MM-DD.")
    if ed in ("TYPE_ERROR", "MALFORMED"):
        client = _select_active_client()
        if client:
            _log(client.get("id"), "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "end_date is malformed. Use YYYY, YYYY-MM, or YYYY-MM-DD.")
    if isinstance(sd, datetime.date) and isinstance(ed, datetime.date) and sd > ed:
        client = _select_active_client()
        if client:
            _log(client.get("id"), "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_date must be on or before end_date.")

    # ---- Resolve ambient authenticated client ----
    api_client = _select_active_client()
    if not api_client:
        # No working combination in store
        _log(None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized API client context available.")
    if api_client.get("status") != "active":
        _log(api_client.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API client is not active.", api_client_id=api_client.get("id"), status=api_client.get("status"))

    limit_err = _check_limits(api_client)
    if limit_err:
        _log(api_client.get("id"), "error", limit_err["error"]["code"])
        return limit_err

    # ---- Create search_requests row and perform lifecycle transitions ----
    reqs = _load("search_requests.json")
    if not isinstance(reqs, list):
        reqs = []

    sr_id = _new_id("pmc_srch")
    sr = {
        "id": sr_id,
        "api_client_id": api_client.get("id"),
        "tool_name": "search_pubmed_advanced",
        "key_words": None,
        "term": term,
        "title": title,
        "author": author,
        "journal": journal,
        "start_date": start_date,
        "end_date": end_date,
        "num_results": num_results,
        "pubmed_query": None,
        "status": "queued",
        "pubmed_esearch_webenv": None,
        "pubmed_esearch_query_key": None,
        "result_count_total": None,
        "result_count_returned": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    reqs.append(sr)
    _save("search_requests.json", reqs)

    # Transition queued -> running
    sr["status"] = "running"
    sr["started_at"] = now_iso
    sr["updated_at"] = now_iso
    _save("search_requests.json", reqs)

    # Offline "search": pick existing articles as results, deterministic-ish ordering by pmid asc.
    arts = _load("articles.json")
    if not isinstance(arts, list):
        arts = []
    def _norm(s):
        return (s or "").strip().lower()

    q = " AND ".join([p for p in [
        (f"{term}" if term else None),
        (f"{title}[Title]" if title else None),
        (f"{author}[Author]" if author else None),
        (f"{journal}[Journal]" if journal else None),
        (f"{start_date}:{end_date}[Date]" if (start_date or end_date) else None),
    ] if p])
    sr["pubmed_query"] = q if q else None

    matched = []
    t_term = _norm(term)
    t_title = _norm(title)
    t_author = _norm(author)
    t_journal = _norm(journal)

    for a in arts:
        if not isinstance(a, dict):
            continue
        pmid = a.get("pmid")
        if not isinstance(pmid, int) or pmid <= 0:
            continue
        ok = True
        if term:
            blob = " ".join([_norm(a.get("title")), _norm(a.get("abstract")), _norm(a.get("journal"))])
            if t_term not in blob:
                ok = False
        if ok and title:
            if t_title not in _norm(a.get("title")):
                ok = False
        if ok and author:
            auths = a.get("authors")
            if isinstance(auths, list):
                ablob = " ".join([_norm(x) for x in auths if isinstance(x, str)])
            else:
                ablob = ""
            if t_author not in ablob:
                ok = False
        if ok and journal:
            if t_journal not in _norm(a.get("journal")):
                ok = False
        # Date filtering: only if publication_date exists and looks like ISO-ish; otherwise do not exclude.
        if ok and (isinstance(sd, datetime.date) or isinstance(ed, datetime.date)):
            pd = a.get("publication_date")
            pd_date = None
            if isinstance(pd, str):
                pds = pd.strip()
                # Try parse YYYY-MM-DD or YYYY-MM or YYYY
                pd_date = _parse_date(pds) if pds else None
                if pd_date in ("TYPE_ERROR", "MALFORMED"):
                    pd_date = None
            if pd_date is not None:
                if isinstance(sd, datetime.date) and pd_date < sd:
                    ok = False
                if ok and isinstance(ed, datetime.date) and pd_date > ed:
                    ok = False
        if ok:
            matched.append(a)

    matched.sort(key=lambda x: x.get("pmid") if isinstance(x.get("pmid"), int) else 10**18)

    total = len(matched)
    returned = matched[:num_results]

    # Persist results
    sres = _load("search_results.json")
    if not isinstance(sres, list):
        sres = []
    existing_pairs = set()
    for r in sres:
        if isinstance(r, dict) and r.get("search_request_id") == sr_id and isinstance(r.get("pmid"), int):
            existing_pairs.add(r.get("pmid"))

    inserted = 0
    rank = 1
    for a in returned:
        pmid = a.get("pmid")
        art_id = a.get("id")
        if pmid in existing_pairs:
            continue
        # enforce uniqueness (search_request_id, rank) by ensuring rank increments only on insert
        row = {
            "id": _new_id("pmc_sres"),
            "search_request_id": sr_id,
            "article_id": art_id,
            "pmid": pmid,
            "rank": rank,
            "score": None,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        sres.append(row)
        existing_pairs.add(pmid)
        inserted += 1
        rank += 1

    _save("search_results.json", sres)

    # Finish request
    sr["status"] = "succeeded"
    sr["result_count_total"] = int(total)
    sr["result_count_returned"] = int(min(num_results, total))
    sr["finished_at"] = now_iso
    sr["updated_at"] = now_iso
    _save("search_requests.json", reqs)

    # Log successful call
    _log(api_client.get("id"), "ok", None)

    # Return envelope: request + articles (records) + metadata
    return {
        "search_request": sr,
        "articles": returned,
        "meta": {
            "total_available": total,
            "returned": sr["result_count_returned"]
        }
    }

def get_pubmed_article_metadata(pmid, **_extra):
    import json, os, datetime, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0306000" if __import__("os").path.isdir("./environment_mix/0306000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(api_client_id, tool, status, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
            "api_client_id": api_client_id,
            "tool_name": tool,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _select_active_client_that_can_call():
        clients = _load("api_clients.json")
        if not isinstance(clients, list): clients = []
        for c in clients:
            if isinstance(c, dict) and c.get("status") == "active":
                rpm = c.get("requests_per_minute_limit")
                daily = c.get("daily_request_limit")
                if isinstance(rpm, int) and isinstance(daily, int) and rpm >= 1 and daily >= 1:
                    return c
        return None

    client = _select_active_client_that_can_call()
    if not client:
        _log(None, "get_pubmed_article_metadata", "error", (time.time()-t0)*1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized API client context available.")
    api_client_id = client["id"]

    # Validate pmid
    pmid_int = None
    if isinstance(pmid, int):
        pmid_int = pmid
    elif isinstance(pmid, str):
        s = pmid.strip()
        if s.isdigit():
            try:
                pmid_int = int(s)
            except Exception:
                pmid_int = None
    if not isinstance(pmid_int, int) or pmid_int <= 0:
        _log(api_client_id, "get_pubmed_article_metadata", "error", (time.time()-t0)*1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "pmid must be a positive integer (or numeric string).")

    articles = _load("articles.json")
    if not isinstance(articles, list): articles = []

    def _find_by_pmid(pmidv):
        for a in articles:
            if isinstance(a, dict) and a.get("pmid") == pmidv:
                return a
        return None

    # Offline resolution rule: treat extremely large as not resolvable
    if pmid_int > 200000000:
        _log(api_client_id, "get_pubmed_article_metadata", "error", (time.time()-t0)*1000, "NOT_FOUND")
        return _err("NOT_FOUND", "No PubMed record found for the given PMID.", pmid=pmid_int)

    ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    a = _find_by_pmid(pmid_int)
    if a:
        # upsert update on successful fetch
        if a.get("status") == "withdrawn":
            # withdrawn still exists; update fetch timestamps
            a["last_fetched_at"] = ts
            a["updated_at"] = ts
            _save("articles.json", articles)
            _log(api_client_id, "get_pubmed_article_metadata", "ok", (time.time()-t0)*1000, None)
            return {"article": a}
        a["last_fetched_at"] = ts
        a["updated_at"] = ts
        # If placeholder unavailable, "fetch" fills some fields and may set active
        if a.get("status") == "unavailable":
            a["status"] = "active"
            if not a.get("title"):
                a["title"] = f"PubMed Article {pmid_int}"
            if not a.get("source_url"):
                a["source_url"] = f"https://pubmed.ncbi.nlm.nih.gov/{pmid_int}/"
        _save("articles.json", articles)
        _log(api_client_id, "get_pubmed_article_metadata", "ok", (time.time()-t0)*1000, None)
        return {"article": a}

    # Insert new cached article (upsert)
    art_id = f"art_{pmid_int}"
    existing_ids = {x.get("id") for x in articles if isinstance(x, dict)}
    if art_id in existing_ids:
        art_id = f"{art_id}_{int(time.time()*1000)}_{random.randint(1000,9999)}"

    new_a = {
        "id": art_id,
        "pmid": pmid_int,
        "status": "active",
        "title": f"PubMed Article {pmid_int}",
        "abstract": None,
        "journal": None,
        "publication_date": None,
        "authors": None,
        "doi": None,
        "pmc_id": None,
        "mesh_terms": None,
        "keywords": None,
        "source_url": f"https://pubmed.ncbi.nlm.nih.gov/{pmid_int}/",
        "last_fetched_at": ts,
        "created_at": ts,
        "updated_at": ts
    }
    # enforce unique(pmid)
    if _find_by_pmid(pmid_int):
        a = _find_by_pmid(pmid_int)
        if a:
            a["last_fetched_at"] = ts
            a["updated_at"] = ts
            _save("articles.json", articles)
            _log(api_client_id, "get_pubmed_article_metadata", "ok", (time.time()-t0)*1000, None)
            return {"article": a}

    articles.append(new_a)
    _save("articles.json", articles)
    _log(api_client_id, "get_pubmed_article_metadata", "ok", (time.time()-t0)*1000, None)
    return {"article": new_a}

def download_pubmed_pdf(pmid, **_extra):
    import json, os, datetime, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0306000" if __import__("os").path.isdir("./environment_mix/0306000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(api_client_id, tool, status, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
            "api_client_id": api_client_id,
            "tool_name": tool,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _select_active_client_that_can_call():
        clients = _load("api_clients.json")
        if not isinstance(clients, list): clients = []
        for c in clients:
            if isinstance(c, dict) and c.get("status") == "active":
                rpm = c.get("requests_per_minute_limit")
                daily = c.get("daily_request_limit")
                if isinstance(rpm, int) and isinstance(daily, int) and rpm >= 1 and daily >= 1:
                    return c
        return None

    def _enforce_limits(api_client_id):
        clients = _load("api_clients.json")
        if not isinstance(clients, list): clients = []
        client = next((c for c in clients if isinstance(c, dict) and c.get("id") == api_client_id), None)
        if not client:
            return _err("UNAUTHORIZED", "No authorized API client context available.")
        if client.get("status") != "active":
            return _err("UNAUTHORIZED", "API client is not active.", api_client_id=api_client_id, status=client.get("status"))

        rpm_limit = client.get("requests_per_minute_limit")
        daily_limit = client.get("daily_request_limit")
        if not isinstance(rpm_limit, int) or not isinstance(daily_limit, int):
            return _err("VALIDATION_ERROR", "Client limits are misconfigured.", api_client_id=api_client_id)

        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []

        now_dt = datetime.datetime.utcnow()
        one_min_ago = now_dt - datetime.timedelta(minutes=1)
        day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)

        def _parse_ts(s):
            if not isinstance(s, str): return None
            try:
                if s.endswith("Z"): s2 = s[:-1]
                else: s2 = s
                return datetime.datetime.fromisoformat(s2)
            except Exception:
                return None

        rpm_count = 0
        daily_count = 0
        for r in logs:
            if not isinstance(r, dict): 
                continue
            if r.get("api_client_id") != api_client_id:
                continue
            ts = _parse_ts(r.get("created_at"))
            if not ts:
                continue
            if ts >= one_min_ago:
                rpm_count += 1
            if ts >= day_start:
                daily_count += 1

        if rpm_count >= rpm_limit:
            return _err("RATE_LIMIT", "Requests per minute limit exceeded.", limit=rpm_limit, window_seconds=60)
        if daily_count >= daily_limit:
            return _err("QUOTA_EXCEEDED", "Daily request limit exceeded.", limit=daily_limit, window="day")
        return None

    client = _select_active_client_that_can_call()
    if not client:
        _log(None, "download_pubmed_pdf", "error", (time.time()-t0)*1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized API client context available.")
    api_client_id = client["id"]

    # Validate pmid
    pmid_int = None
    if isinstance(pmid, int):
        pmid_int = pmid
    elif isinstance(pmid, str):
        s = pmid.strip()
        if s.isdigit():
            try:
                pmid_int = int(s)
            except Exception:
                pmid_int = None
    if not isinstance(pmid_int, int) or pmid_int <= 0:
        _log(api_client_id, "download_pubmed_pdf", "error", (time.time()-t0)*1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "pmid must be a positive integer (or numeric string).")

    limerr = _enforce_limits(api_client_id)
    if limerr:
        _log(api_client_id, "download_pubmed_pdf", "error", (time.time()-t0)*1000, limerr["error"]["code"])
        return limerr

    articles = _load("articles.json")
    if not isinstance(articles, list): articles = []
    pdf_downloads = _load("pdf_downloads.json")
    if not isinstance(pdf_downloads, list): pdf_downloads = []

    def _find_article_by_pmid(pmidv):
        for a in articles:
            if isinstance(a, dict) and a.get("pmid") == pmidv:
                return a
        return None

    def _create_placeholder_article(pmidv):
        art_id = f"art_{pmidv}"
        existing_ids = {x.get("id") for x in articles if isinstance(x, dict)}
        if art_id in existing_ids:
            art_id = f"{art_id}_{int(time.time()*1000)}_{random.randint(1000,9999)}"
        ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        return {
            "id": art_id,
            "pmid": pmidv,
            "status": "unavailable",
            "title": None,
            "abstract": None,
            "journal": None,
            "publication_date": None,
            "authors": None,
            "doi": None,
            "pmc_id": None,
            "mesh_terms": None,
            "keywords": None,
            "source_url": f"https://pubmed.ncbi.nlm.nih.gov/{pmidv}/",
            "last_fetched_at": None,
            "created_at": ts,
            "updated_at": ts
        }

    art = _find_article_by_pmid(pmid_int)
    if not art:
        # ensure unique(pmid)
        if not _find_article_by_pmid(pmid_int):
            art = _create_placeholder_article(pmid_int)
            articles.append(art)
            _save("articles.json", articles)
        else:
            art = _find_article_by_pmid(pmid_int)

    if not art:
        _log(api_client_id, "download_pubmed_pdf", "error", (time.time()-t0)*1000, "NOT_FOUND")
        return _err("NOT_FOUND", "Article could not be created or resolved.", pmid=pmid_int)

    # Conflict checks: in-progress or succeeded for same client+pmid
    in_progress_statuses = {"queued", "resolving", "downloading"}
    for d in pdf_downloads:
        if not isinstance(d, dict):
            continue
        if d.get("api_client_id") == api_client_id and d.get("pmid") == pmid_int:
            st = d.get("status")
            if st in in_progress_statuses:
                _log(api_client_id, "download_pubmed_pdf", "error", (time.time()-t0)*1000, "CONFLICT")
                return _err("CONFLICT", "A download is already in progress for this PMID.", download_id=d.get("id"), status=st)
            if st == "succeeded":
                _log(api_client_id, "download_pubmed_pdf", "error", (time.time()-t0)*1000, "CONFLICT")
                return _err("CONFLICT", "A completed download already exists for this PMID.", download_id=d.get("id"), status=st)

    # Create queued download row
    req_ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    dl_id = f"pdf_{int(time.time()*1000)}_{random.randint(1000,9999)}"
    dl = {
        "id": dl_id,
        "api_client_id": api_client_id,
        "article_id": art["id"],
        "pmid": pmid_int,
        "status": "queued",
        "resolved_pdf_url": None,
        "resolved_landing_url": None,
        "storage_provider": None,
        "storage_path": None,
        "content_type": None,
        "file_size_bytes": None,
        "http_status_code": None,
        "error_message": None,
        "requested_at": req_ts,
        "completed_at": None,
        "created_at": req_ts,
        "updated_at": req_ts
    }
    pdf_downloads.append(dl)
    _save("pdf_downloads.json", pdf_downloads)

    # queued -> resolving
    dl["status"] = "resolving"
    dl["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("pdf_downloads.json", pdf_downloads)

    # Offline resolution policy:
    # - If article has pmc_id starting with PMC => succeed (open access)
    # - Else: even PMID succeeds, odd PMID not_found
    def _can_resolve_pdf(article, pmidv):
        pmc = article.get("pmc_id")
        if isinstance(pmc, str) and pmc.startswith("PMC"):
            return True
        return (pmidv % 2) == 0

    try:
        if not _can_resolve_pdf(art, pmid_int):
            # resolving -> not_found
            dl["status"] = "not_found"
            dl["http_status_code"] = 404
            dl["error_message"] = "No full-text PDF link could be resolved for this article."
            dl["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            dl["updated_at"] = dl["completed_at"]
            _save("pdf_downloads.json", pdf_downloads)
            _log(api_client_id, "download_pubmed_pdf", "error", (time.time()-t0)*1000, "NOT_FOUND")
            return _err("NOT_FOUND", "No full-text/PDF link could be resolved for the given PMID.", download=dl)

        # resolving -> downloading
        dl["status"] = "downloading"
        dl["resolved_pdf_url"] = f"https://example.org/pubmed/{pmid_int}.pdf"
        dl["resolved_landing_url"] = art.get("source_url") or f"https://pubmed.ncbi.nlm.nih.gov/{pmid_int}/"
        dl["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("pdf_downloads.json", pdf_downloads)

        # downloading -> succeeded (enforce required fields)
        ts_done = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        dl["status"] = "succeeded"
        dl["storage_provider"] = "local"
        dl["storage_path"] = __import__("os").path.join(_DB, f"pdfs/{pmid_int}.pdf")
        dl["content_type"] = "application/pdf"
        dl["file_size_bytes"] = int(100000 + (pmid_int % 900000))  # deterministic-ish nonzero
        dl["http_status_code"] = 200
        dl["error_message"] = None
        dl["completed_at"] = ts_done
        dl["updated_at"] = ts_done

        if dl["storage_provider"] is None or dl["storage_path"] is None or dl["file_size_bytes"] is None:
            # illegal per schema
            dl["status"] = "failed"
            dl["error_message"] = "Internal storage fields missing for succeeded download."
            dl["completed_at"] = ts_done
            dl["updated_at"] = ts_done
            _save("pdf_downloads.json", pdf_downloads)
            _log(api_client_id, "download_pubmed_pdf", "error", (time.time()-t0)*1000, "FAILED")
            return _err("NOT_FOUND", "Download failed.", download=dl)

        _save("pdf_downloads.json", pdf_downloads)
        _log(api_client_id, "download_pubmed_pdf", "ok", (time.time()-t0)*1000, None)
        return {"download": dl}
    except Exception as e:
        # resolving/downloading -> failed
        ts_done = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        dl["status"] = "failed"
        dl["error_message"] = str(e)
        dl["completed_at"] = ts_done
        dl["updated_at"] = ts_done
        _save("pdf_downloads.json", pdf_downloads)
        _log(api_client_id, "download_pubmed_pdf", "error", (time.time()-t0)*1000, "FAILED")
        return _err("NOT_FOUND", "Download failed.", details=str(e), download=dl)

def list_search_requests(api_key, status=None, tool_name=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib, hmac
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0306000" if __import__("os").path.isdir("./environment_mix/0306000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1]
            dt = datetime.datetime.fromisoformat(ss)
            return dt
        except Exception:
            return None

    def _log(api_client_id, tool, status_str, error_code=None):
        latency_ms = int((time.time() - _t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rlog_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "api_client_id": api_client_id,
            "tool_name": tool,
            "status": status_str,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now_iso
        })
        _save("request_logs.json", logs)

    def _check_limits(api_client_id, rpm_limit, daily_limit):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        win_start = now - datetime.timedelta(seconds=60)
        day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
        c60 = 0
        cday = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_client_id") != api_client_id:
                continue
            ts = r.get("created_at")
            dt = _parse_iso(ts) if isinstance(ts, str) else None
            if dt is None:
                continue
            if dt >= win_start:
                c60 += 1
            if dt >= day_start:
                cday += 1
        if isinstance(rpm_limit, int) and c60 >= rpm_limit:
            return _err("RATE_LIMIT", "Requests per minute limit exceeded.", limit=rpm_limit, window_seconds=60)
        if isinstance(daily_limit, int) and cday >= daily_limit:
            return _err("QUOTA_EXCEEDED", "Daily request limit exceeded.", limit=daily_limit, window="day")
        return None

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string.")
    if status is not None and status not in ("queued", "running", "succeeded", "failed"):
        return _err("VALIDATION_ERROR", "Invalid status.", allowed=["queued", "running", "succeeded", "failed"])
    if tool_name is not None and tool_name not in ("search_pubmed_key_words", "search_pubmed_advanced"):
        return _err("VALIDATION_ERROR", "Invalid tool_name.", allowed=["search_pubmed_key_words", "search_pubmed_advanced"])
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    ca = _parse_iso(created_after)
    if created_after is not None and ca is None:
        return _err("VALIDATION_ERROR", "created_after must be an ISO-8601 timestamp string or null.")
    cb = _parse_iso(created_before)
    if created_before is not None and cb is None:
        return _err("VALIDATION_ERROR", "created_before must be an ISO-8601 timestamp string or null.")

    # Authenticate by matching api_key against stored api_key_hash using common schemes
    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        clients = []
    matched_client = None
    api_key_in = api_key.strip()

    def _looks_hex(s):
        try:
            int(s, 16)
            return len(s) % 2 == 0
        except Exception:
            return False

    for c in clients:
        if not isinstance(c, dict):
            continue
        h = c.get("api_key_hash")
        if not isinstance(h, str) or not h:
            continue
        # Allow direct match to stored client-visible value if vendor stores plaintext in this field (rare).
        if h == api_key_in:
            matched_client = c
            break
        # Try SHA-256 hex
        sha256_hex = hashlib.sha256(api_key_in.encode("utf-8")).hexdigest()
        if h == sha256_hex:
            matched_client = c
            break
        # Try SHA-1 hex
        sha1_hex = hashlib.sha1(api_key_in.encode("utf-8")).hexdigest()
        if h == sha1_hex:
            matched_client = c
            break
        # Try PBKDF2 forms: "pbkdf2_sha256$iter$salt$hex" or "$"
        if h.startswith("pbkdf2_sha256$"):
            parts = h.split("$")
            if len(parts) == 4:
                _, it_s, salt, dk = parts
                try:
                    it = int(it_s)
                    dkk = hashlib.pbkdf2_hmac("sha256", api_key_in.encode("utf-8"), salt.encode("utf-8"), it).hex()
                    if hmac.compare_digest(dkk, dk):
                        matched_client = c
                        break
                except Exception:
                    pass
        if h.startswith("pbkdf2_sha1$"):
            parts = h.split("$")
            if len(parts) == 4:
                _, it_s, salt, dk = parts
                try:
                    it = int(it_s)
                    dkk = hashlib.pbkdf2_hmac("sha1", api_key_in.encode("utf-8"), salt.encode("utf-8"), it).hex()
                    if hmac.compare_digest(dkk, dk):
                        matched_client = c
                        break
                except Exception:
                    pass

    if matched_client is None:
        # No workable credential in store
        _log(None, "list_search_requests", "error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key.")

    api_client_id = matched_client.get("id")
    if matched_client.get("status") in ("suspended", "deleted"):
        _log(api_client_id, "list_search_requests", "error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API client is not active.")
    rpm_limit = matched_client.get("requests_per_minute_limit")
    daily_limit = matched_client.get("daily_request_limit")
    lim_err = _check_limits(api_client_id, rpm_limit, daily_limit)
    if lim_err:
        _log(api_client_id, "list_search_requests", "error", error_code=lim_err["error"]["code"])
        return lim_err

    # Cursor format: base64url(json({"offset": int}))
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            _log(api_client_id, "list_search_requests", "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string or null.")
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "offset" not in obj or not isinstance(obj["offset"], int) or obj["offset"] < 0:
                raise ValueError("bad cursor")
            offset = obj["offset"]
        except Exception:
            _log(api_client_id, "list_search_requests", "error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    reqs = _load("search_requests.json")
    if not isinstance(reqs, list):
        reqs = []

    filtered = []
    for r in reqs:
        if not isinstance(r, dict):
            continue
        if r.get("api_client_id") != api_client_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        r_created = _parse_iso(r.get("created_at")) if isinstance(r.get("created_at"), str) else None
        if ca is not None and (r_created is None or r_created < ca):
            continue
        if cb is not None and (r_created is None or r_created > cb):
            continue
        filtered.append(r)

    # Newest first by created_at then id
    def _sort_key(r):
        dt = _parse_iso(r.get("created_at")) if isinstance(r.get("created_at"), str) else None
        ts = dt.timestamp() if dt else 0.0
        return (ts, r.get("id") or "")
    filtered.sort(key=_sort_key, reverse=True)

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("utf-8").rstrip("=")

    _log(api_client_id, "list_search_requests", "ok", error_code=None)
    return {
        "data": page,
        "page": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total
        }
    }

def get_search_request(api_key, id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0306000" if __import__("os").path.isdir("./environment_mix/0306000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _gen_id(prefix):
        import secrets
        return f"{prefix}_{int(time.time()*1000)}_{secrets.token_hex(6)}"

    def _append_log(api_client_id, status_str, error_code=None):
        latency_ms = int((time.time() - _t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("rlog"),
            "api_client_id": api_client_id,
            "tool_name": "get_search_request",
            "status": status_str,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now_iso
        })
        _save("request_logs.json", logs)

    def _match_client_for_api_key(api_key_value):
        # IMPORTANT: authenticate against a client-visible value (id OR stored api_key_hash field which
        # in this datastore acts as the only available token string).
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        key = api_key_value.strip()
        clients = _load("api_clients.json")
        if not isinstance(clients, list):
            return None

        # Prefer active clients when multiple could match.
        active_match = None
        any_match = None
        for c in clients:
            if not isinstance(c, dict):
                continue
            if key == c.get("id") or key == c.get("api_key_hash"):
                any_match = any_match or c
                if c.get("status") == "active":
                    active_match = c
                    break
        return active_match or any_match

    def _enforce_rate_limits(api_client_id):
        clients = _load("api_clients.json")
        if not isinstance(clients, list):
            return _err("UNAUTHORIZED", "Access denied.")
        client = next((c for c in clients if isinstance(c, dict) and c.get("id") == api_client_id), None)
        if not client:
            return _err("UNAUTHORIZED", "Access denied.")
        if client.get("status") != "active":
            return _err("UNAUTHORIZED", "Client is not active.", status=client.get("status"))

        rpm = client.get("requests_per_minute_limit")
        daily = client.get("daily_request_limit")
        if not isinstance(rpm, int) or not isinstance(daily, int):
            return _err("VALIDATION_ERROR", "Client limits are misconfigured.")

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now_dt = now
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_ago = now_dt - datetime.timedelta(days=1)

        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_client_id") != api_client_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                rdt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if rdt >= minute_ago:
                per_min += 1
            if rdt >= day_ago:
                per_day += 1

        if per_min >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit=rpm, window_seconds=60)
        if per_day >= daily:
            return _err("QUOTA_EXCEEDED", "Daily request limit exceeded.", limit=daily, window_days=1)
        return None

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _append_log(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(id, str) or not id.strip():
        client_guess = _match_client_for_api_key(api_key)
        _append_log(client_guess.get("id") if isinstance(client_guess, dict) else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a non-empty string.")

    client = _match_client_for_api_key(api_key)
    if not isinstance(client, dict):
        _append_log(None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Access denied.")

    api_client_id = client.get("id")
    limit_err = _enforce_rate_limits(api_client_id)
    if limit_err:
        _append_log(api_client_id, "error", limit_err["error"]["code"])
        return limit_err

    # Fetch request
    reqs = _load("search_requests.json")
    if not isinstance(reqs, list):
        _append_log(api_client_id, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "search_request not found.", id=id)

    row = next((r for r in reqs if isinstance(r, dict) and r.get("id") == id), None)
    if not row:
        _append_log(api_client_id, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "search_request not found.", id=id)

    if row.get("api_client_id") != api_client_id:
        _append_log(api_client_id, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Access denied.")

    _append_log(api_client_id, "ok", None)
    return {"search_request": row}

