            return _err("VALIDATION_ERROR", "Client limits are misconfigured.")

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now_dt = now
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_ago = now_dt - datetime.timedelta(days=1)

        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_client_id") != api_client_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                rdt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if rdt >= minute_ago:
                per_min += 1
            if rdt >= day_ago:
                per_day += 1

        if per_min >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit=rpm, window_seconds=60)
        if per_day >= daily:
            return _err("QUOTA_EXCEEDED", "Daily request limit exceeded.", limit=daily, window_days=1)
        return None

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str):
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("offset:"):
                return None
            off = int(s.split(":", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(off):
        s = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("utf-8").rstrip("=")

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _append_log(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(search_request_id, str) or not search_request_id.strip():
        client_guess = _match_client_for_api_key(api_key)
        _append_log(client_guess.get("id") if isinstance(client_guess, dict) else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "search_request_id must be a non-empty string.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int):
        client_guess = _match_client_for_api_key(api_key)
        _append_log(client_guess.get("id") if isinstance(client_guess, dict) else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 500:
        client_guess = _match_client_for_api_key(api_key)
        _append_log(client_guess.get("id") if isinstance(client_guess, dict) else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 500.", minimum=1, maximum=500)

    offset = _decode_cursor(cursor)
    if offset is None:
        client_guess = _match_client_for_api_key(api_key)
        _append_log(client_guess.get("id") if isinstance(client_guess, dict) else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    client = _match_client_for_api_key(api_key)
    if not isinstance(client, dict):
        _append_log(None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Access denied.")
    api_client_id = client.get("id")

    limit_err = _enforce_rate_limits(api_client_id)
    if limit_err:
        _append_log(api_client_id, "error", limit_err["error"]["code"])
        return limit_err

    # Ensure parent exists and is owned by caller
    reqs = _load("search_requests.json")
    if not isinstance(reqs, list):
        _append_log(api_client_id, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "search_request not found.", id=search_request_id)

    parent = next((r for r in reqs if isinstance(r, dict) and r.get("id") == search_request_id), None)
    if not parent:
        _append_log(api_client_id, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "search_request not found.", id=search_request_id)
    if parent.get("api_client_id") != api_client_id:
        _append_log(api_client_id, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Access denied.")

    # Load and filter results
    results = _load("search_results.json")
    if not isinstance(results, list):
        results = []

    rows = [r for r in results if isinstance(r, dict) and r.get("search_request_id") == search_request_id]
    # Order by rank asc (stable)
    def _rank_key(r):
        v = r.get("rank")
        return v if isinstance(v, int) else 10**18
    rows.sort(key=_rank_key)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor(next_offset) if has_more else None

    _append_log(api_client_id, "ok", None)
    return {
        "search_results": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }

def get_pdf_download(api_key, id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0306000" if __import__("os").path.isdir("./environment_mix/0306000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _gen_id(prefix):
        import secrets
        return f"{prefix}_{int(time.time()*1000)}_{secrets.token_hex(6)}"

    def _append_log(api_client_id, status_str, error_code=None):
        latency_ms = int((time.time() - _t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("rlog"),
            "api_client_id": api_client_id,
            "tool_name": "get_pdf_download",
            "status": status_str,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now_iso
        })
        _save("request_logs.json", logs)

    def _match_client_for_api_key(api_key_value):
        # Authenticate against client-visible value: id OR stored api_key_hash string (the only token-like field present).
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        key = api_key_value.strip()
        clients = _load("api_clients.json")
        if not isinstance(clients, list):
            return None
        active_match = None
        any_match = None
        for c in clients:
            if not isinstance(c, dict):
                continue
            if key == c.get("id") or key == c.get("api_key_hash"):
                any_match = any_match or c
                if c.get("status") == "active":
                    active_match = c
                    break
        return active_match or any_match

    def _enforce_rate_limits(api_client_id):
        clients = _load("api_clients.json")
        if not isinstance(clients, list):
            return _err("UNAUTHORIZED", "Access denied.")
        client = next((c for c in clients if isinstance(c, dict) and c.get("id") == api_client_id), None)
        if not client:
            return _err("UNAUTHORIZED", "Access denied.")
        if client.get("status") != "active":
            return _err("UNAUTHORIZED", "Client is not active.", status=client.get("status"))

        rpm = client.get("requests_per_minute_limit")
        daily = client.get("daily_request_limit")
        if not isinstance(rpm, int) or not isinstance(daily, int):
            return _err("VALIDATION_ERROR", "Client limits are misconfigured.")

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now_dt = now
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_ago = now_dt - datetime.timedelta(days=1)

        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_client_id") != api_client_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                rdt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if rdt >= minute_ago:
                per_min += 1
            if rdt >= day_ago:
                per_day += 1

        if per_min >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit=rpm, window_seconds=60)
        if per_day >= daily:
            return _err("QUOTA_EXCEEDED", "Daily request limit exceeded.", limit=daily, window_days=1)
        return None

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _append_log(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(id, str) or not id.strip():
        client_guess = _match_client_for_api_key(api_key)
        _append_log(client_guess.get("id") if isinstance(client_guess, dict) else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a non-empty string.")

    client = _match_client_for_api_key(api_key)
    if not isinstance(client, dict):
        _append_log(None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Access denied.")
    api_client_id = client.get("id")

    limit_err = _enforce_rate_limits(api_client_id)
    if limit_err:
        _append_log(api_client_id, "error", limit_err["error"]["code"])
        return limit_err

    dls = _load("pdf_downloads.json")
    if not isinstance(dls, list):
        _append_log(api_client_id, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "pdf_download not found.", id=id)

    row = next((r for r in dls if isinstance(r, dict) and r.get("id") == id), None)
    if not row:
        _append_log(api_client_id, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "pdf_download not found.", id=id)

    if row.get("api_client_id") != api_client_id:
        _append_log(api_client_id, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Access denied.")

    _append_log(api_client_id, "ok", None)
    return {"pdf_download": row}

def list_pdf_downloads(api_key, status=None, pmid=None, article_id=None, requested_after=None, requested_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0306000" if __import__("os").path.isdir("./environment_mix/0306000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- validation (no auth side effects yet) ----
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if status is not None:
        allowed = {"queued", "resolving", "downloading", "succeeded", "not_found", "forbidden", "failed"}
        if not isinstance(status, str) or status not in allowed:
            return _err("VALIDATION_ERROR", "Invalid status", allowed=list(sorted(allowed)))
    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    pmid_int = None
    if pmid is not None:
        if isinstance(pmid, int):
            pmid_int = pmid
        elif isinstance(pmid, str):
            s = pmid.strip()
            if not s:
                return _err("VALIDATION_ERROR", "pmid must not be empty when provided")
            if not s.isdigit():
                return _err("VALIDATION_ERROR", "pmid must be an integer or numeric string")
            try:
                pmid_int = int(s)
            except Exception:
                return _err("VALIDATION_ERROR", "pmid is not a valid integer")
        else:
            return _err("VALIDATION_ERROR", "pmid must be an integer, string, or null")
        if pmid_int <= 0:
            return _err("VALIDATION_ERROR", "pmid must be > 0")

    if article_id is not None and (not isinstance(article_id, str) or not article_id.strip()):
        return _err("VALIDATION_ERROR", "article_id must be a non-empty string or null")

    def _parse_iso_z(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 timestamp string or null")
        st = s.strip()
        try:
            if st.endswith("Z"):
                return datetime.datetime.fromisoformat(st[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(st)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return _err("VALIDATION_ERROR", f"{field} must be a valid ISO-8601 timestamp")
    ra = _parse_iso_z(requested_after, "requested_after")
    if isinstance(ra, dict) and "error" in ra:
        return ra
    rb = _parse_iso_z(requested_before, "requested_before")
    if isinstance(rb, dict) and "error" in rb:
        return rb
    if ra is not None and rb is not None and ra > rb:
        return _err("VALIDATION_ERROR", "requested_after must be <= requested_before")

    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string or null")

    # ---- authenticate api_key (must not compare against hash ciphertext) ----
    api_clients = _load("api_clients.json")
    client = None
    # Prefer exact id match if api_key equals an id
    for c in api_clients:
        if isinstance(c, dict) and c.get("id") == api_key:
            client = c
            break
    # Otherwise allow matching by stored api_key_hash ONLY if it is actually a stored client-visible value.
    # Since vendor stores only a hash, we accept either exact match to api_key_hash or sha256(api_key) match.
    if client is None:
        key = api_key.strip()
        sha = hashlib.sha256(key.encode("utf-8")).hexdigest()
        for c in api_clients:
            if not isinstance(c, dict):
                continue
            h = c.get("api_key_hash")
            if h == key or h == sha:
                client = c
                break
    if client is None:
        # log attempt (unauthorized)
        search_requests = _load("search_requests.json")  # unused but loaded to avoid missing file patterns
        pdf_downloads = _load("pdf_downloads.json")
        # lightweight request log via search_requests? None available. No audit collection in schema.
        # Enforce "must not raise": return error.
        return _err("UNAUTHORIZED", "Invalid API key")

    if client.get("status") in ("suspended", "deleted"):
        return _err("UNAUTHORIZED", "Client is not active", status=client.get("status"))

    client_id = client.get("id")
    if not isinstance(client_id, str) or not client_id:
        return _err("UNAUTHORIZED", "Authenticated client record is invalid")

    # ---- rate limits / quotas (reads count too for dynamics, but only block mutations per rules).
    # We compute and return current state, and we do NOT block list reads.
    # Compute using pdf_downloads + search_requests as "requests".
    search_requests = _load("search_requests.json")
    pdf_downloads = _load("pdf_downloads.json")

    def _dt_from_row(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    minute_ago = now_dt - datetime.timedelta(minutes=1)
    day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _count_requests_in_window():
        rpm = 0
        daily = 0
        for r in search_requests:
            if not isinstance(r, dict) or r.get("api_client_id") != client_id:
                continue
            ts = _dt_from_row(r.get("created_at")) or _dt_from_row(r.get("started_at")) or _dt_from_row(r.get("updated_at"))
            if ts is None:
                continue
            if ts >= day_start:
                daily += 1
            if ts >= minute_ago:
                rpm += 1
        for r in pdf_downloads:
            if not isinstance(r, dict) or r.get("api_client_id") != client_id:
                continue
            ts = _dt_from_row(r.get("requested_at")) or _dt_from_row(r.get("created_at")) or _dt_from_row(r.get("updated_at"))
            if ts is None:
                continue
            if ts >= day_start:
                daily += 1
            if ts >= minute_ago:
                rpm += 1
        return rpm, daily

    rpm_used, daily_used = _count_requests_in_window()
    rpm_limit = client.get("requests_per_minute_limit")
    daily_limit = client.get("daily_request_limit")

    # ---- filtering & pagination ----
    # Cursor: base64url(json({"requested_at": "...", "id": "..."}))
    cursor_req_at = None
    cursor_id = None
    if cursor is not None:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            cursor_req_at = obj.get("requested_at")
            cursor_id = obj.get("id")
            if not isinstance(cursor_req_at, str) or not isinstance(cursor_id, str):
                return _err("VALIDATION_ERROR", "Invalid cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # Apply base filter: only this client
    rows = [r for r in pdf_downloads if isinstance(r, dict) and r.get("api_client_id") == client_id]

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if pmid_int is not None:
        rows = [r for r in rows if r.get("pmid") == pmid_int]
    if article_id is not None:
        rows = [r for r in rows if r.get("article_id") == article_id.strip()]

    if ra is not None:
        rows = [r for r in rows if (_dt_from_row(r.get("requested_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) >= ra]
    if rb is not None:
        rows = [r for r in rows if (_dt_from_row(r.get("requested_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)) <= rb]

    # Sort newest first by requested_at, then id desc
    def _sort_key(r):
        dt = _dt_from_row(r.get("requested_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return (dt, r.get("id") or "")
    rows.sort(key=_sort_key, reverse=True)

    # Cursor filtering: return items strictly older than cursor tuple (requested_at, id)
    if cursor_req_at is not None:
        cdt = _dt_from_row(cursor_req_at)
        if cdt is None:
            return _err("VALIDATION_ERROR", "Invalid cursor")
        filtered = []
        for r in rows:
            rdt = _dt_from_row(r.get("requested_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            rid = r.get("id") or ""
            if (rdt < cdt) or (rdt == cdt and rid < cursor_id):
                filtered.append(r)
        rows = filtered

    total = len(rows)
    page = rows[:limit]
    has_more = total > limit

    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_obj = {"requested_at": last.get("requested_at"), "id": last.get("id")}
        raw = json.dumps(next_obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "data": page,
        "meta": {
            "limit": limit,
            "total_matched": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "filters": {
                "status": status,
                "pmid": pmid_int,
                "article_id": article_id,
                "requested_after": requested_after,
                "requested_before": requested_before,
            },
            "rate_limit": {
                "requests_per_minute_limit": rpm_limit,
                "requests_per_minute_used": rpm_used,
                "daily_request_limit": daily_limit,
                "daily_request_used": daily_used,
            },
            "server_time": now,
            "latency_ms": latency_ms,
        },
    }

def get_current_api_client(api_key, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0306000" if __import__("os").path.isdir("./environment_mix/0306000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    api_clients = _load("api_clients.json")
    client = None
    for c in api_clients:
        if isinstance(c, dict) and c.get("id") == api_key:
            client = c
            break
    if client is None:
        key = api_key.strip()
        sha = hashlib.sha256(key.encode("utf-8")).hexdigest()
        for c in api_clients:
            if not isinstance(c, dict):
                continue
            h = c.get("api_key_hash")
            if h == key or h == sha:
                client = c
                break

    if client is None:
        return _err("UNAUTHORIZED", "Invalid API key")

    if client.get("status") in ("suspended", "deleted"):
        return _err("UNAUTHORIZED", "Client is not active", status=client.get("status"))

    client_id = client.get("id")
    if not isinstance(client_id, str) or not client_id:
        return _err("UNAUTHORIZED", "Authenticated client record is invalid")

    # Compute current rate/quota usage based on existing request rows
    search_requests = _load("search_requests.json")
    pdf_downloads = _load("pdf_downloads.json")

    def _dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    minute_ago = now_dt - datetime.timedelta(minutes=1)
    day_start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)

    rpm_used = 0
    daily_used = 0
    for r in search_requests:
        if not isinstance(r, dict) or r.get("api_client_id") != client_id:
            continue
        ts = _dt(r.get("created_at")) or _dt(r.get("started_at")) or _dt(r.get("updated_at"))
        if ts is None:
            continue
        if ts >= day_start:
            daily_used += 1
        if ts >= minute_ago:
            rpm_used += 1
    for r in pdf_downloads:
        if not isinstance(r, dict) or r.get("api_client_id") != client_id:
            continue
        ts = _dt(r.get("requested_at")) or _dt(r.get("created_at")) or _dt(r.get("updated_at"))
        if ts is None:
            continue
        if ts >= day_start:
            daily_used += 1
        if ts >= minute_ago:
            rpm_used += 1

    rpm_limit = client.get("requests_per_minute_limit")
    daily_limit = client.get("daily_request_limit")

    latency_ms = int((time.time() - t0) * 1000)

    # Effective entitlements/scopes are not explicitly modeled; infer from existence of tools.
    entitlements = {
        "can_search": True,
        "can_get_metadata": True,
        "can_download_pdf": True,
        "can_list_pdf_downloads": True,
    }

    return {
        "data": client,
        "meta": {
            "entitlements": entitlements,
            "rate_limit": {
                "requests_per_minute_limit": rpm_limit,
                "requests_per_minute_used": rpm_used,
                "requests_per_minute_remaining": None if not isinstance(rpm_limit, int) else max(0, rpm_limit - rpm_used),
                "daily_request_limit": daily_limit,
                "daily_request_used": daily_used,
                "daily_request_remaining": None if not isinstance(daily_limit, int) else max(0, daily_limit - daily_used),
            },
            "server_time": now,
            "latency_ms": latency_ms,
        },
    }
